const ABSORB_CAP=4,ABSORB_TP=2,ABSORB_RADIUS=1,SITE_TP=4,REGEN_RATE=0.05,REGEN_DELAY=10,AI_REGEN_RATE=0,AI_ABSORB_CEILING=4;
