function markCombat(q,t){if(!t||t.side==='n')return;q.combat=q.combat||{};q.combat[t.team]=q.turn;}
function regenTiles(q,fx){let healed=0;q.combat=q.combat||{};for(let i=0;i<N*N;i++){const t=q.g[i];if(!t||t.support||t.side==='n')continue;if(t.hp>=t.cap)continue;const rate=t.side==='p'?REGEN_RATE:AI_REGEN_RATE;if(!(rate>0))continue;const last=q.combat[t.team];if(last!==undefined&&q.turn-last<REGEN_DELAY)continue;const amt=Math.max(1,Math.ceil(t.cap*rate));t.hp=Math.min(t.cap,t.hp+amt);healed++;if(t.hp>=t.cap&&fx)fx.push({kind:'regen',at:i});}return healed;}
