const SCORE_PER_TECH=100,TECH_TP_MAX=2,TECH_RADIUS_MAX=2,TECH_THRESHOLD_MAX=3;
function absorbTpAt(lv){return ABSORB_TP+(lv||0);}function absorbTp(q){return absorbTpAt(q.upTp||0);}function absorbThresholdAt(lv){return ABSORB_CAP*(2**(lv||0));}function absorbThreshold(q){return absorbThresholdAt(q.upThreshold||0);}function aiAbsorbCeiling(q){return AI_ABSORB_CEILING;}function siteRadiusAt(lv){return ABSORB_RADIUS+(lv||0);}function siteBudgetAt(lv){return SITE_TP+4*(lv||0);}
