function techInfoAt(line,lv){if(line==='tp')return '每块每回合吸收 '+absorbTpAt(lv)+' 个';if(line==='radius'){const r=siteRadiusAt(lv);return '覆盖 '+((2*r+1)*(2*r+1)-1)+' 格 · 站点吞吐 '+siteBudgetAt(lv)+'/回合';}return '阈值 '+absorbThresholdAt(lv)+' · 可自动长到 '+(2*absorbThresholdAt(lv));}function techUI(){const t=$('tech');if(t)t.textContent=(s.tech||0)+' 点';const cb=$('convertScore');if(cb)cb.onclick=techConvert;const box=$('techTree');if(!box)return;const mk=(line,label)=>{const lv=techLevel(s,line),max=techMax(line);const row=document.createElement('div');row.className='tech-row';const info=document.createElement('div');info.className='tech-info';const name=document.createElement('strong');name.textContent=label+' '+lv+' / '+max;const eff=document.createElement('span');const b=document.createElement('button');if(lv>=max){eff.textContent=techInfoAt(line,lv)+'（已满级）';b.textContent='已满级';b.disabled=true;}else{const cost=techCost(line,lv);eff.textContent=techInfoAt(line,lv)+' → '+techInfoAt(line,lv+1);b.textContent='升级 '+cost+' 点';b.disabled=(s.tech||0)<cost;}info.appendChild(name);info.appendChild(eff);b.onclick=()=>techBuy(line);row.appendChild(info);row.appendChild(b);return row;};box.replaceChildren(mk('threshold','自动合成阈值'),mk('tp','吸收吞吐'),mk('radius','收集半径'));}
