function growFighters(q){let count=0,top=0;for(const t of q.g){if(!t?.core||t.side!=='e'||t.kind!=='fighter')continue;if(t.nextGrowth===undefined)t.nextGrowth=q.turn+40;if(q.turn>=t.nextGrowth){t.n*=2;t.nextGrowth+=40;count++;if(t.n>top)top=t.n;}}if(count){log(q,`敌机成长 · ${count} 架核心翻倍（最高 ${fmt(top)}）`);rescale(q);}return count;}
